# 온톨로지 위에서 2단계 관계 찾기 + LLM 이 만든 관계가 그래프에 있는지 검사 (가상 그래프)
EDGES = {
    ("가나전자", "속함", "반도체 섹터"),
    ("가나전자", "속함", "HBM 테마"),
    ("다라소재", "공급", "가나전자"),
    ("다라소재", "속함", "2차전지 테마"),
    ("마바반도체", "속함", "HBM 테마"),
}

def neighbors(node):
    return [(r, b) for a, r, b in EDGES if a == node] + [(f"←{r}", a) for a, r, b in EDGES if b == node]

def two_hop(start):
    out = []
    for r1, mid in neighbors(start):
        for r2, end in neighbors(mid):
            if end != start:
                out.append(f"{start} -{r1}-> {mid} -{r2}-> {end}")
    return out

print("뉴스 엔티티 '다라소재' 에서 두 걸음:")
for path in sorted(two_hop("다라소재")):
    print("  ", path)

generated = [("다라소재", "공급", "가나전자"), ("다라소재", "공급", "마바반도체")]
for g in generated:
    print(g, "→", "그래프에 있음" if g in EDGES else "근거 없는 관계 — 답에서 뺀다")

# 출력
# 뉴스 엔티티 '다라소재' 에서 두 걸음:
#    다라소재 -공급-> 가나전자 -속함-> HBM 테마
#    다라소재 -공급-> 가나전자 -속함-> 반도체 섹터
# ('다라소재', '공급', '가나전자') → 그래프에 있음
# ('다라소재', '공급', '마바반도체') → 근거 없는 관계 — 답에서 뺀다

# 정답셋으로 리트리버 재기 — Recall@3 와 MRR (가상 질문 4개)
gold = {"q1": {"D1"}, "q2": {"D7", "D9"}, "q3": {"D4"}, "q4": {"D2"}}
before = {"q1": ["D3", "D1", "D5"], "q2": ["D7", "D8", "D6"], "q3": ["D5", "D6", "D8"], "q4": ["D2", "D1", "D3"]}
after  = {"q1": ["D1", "D3", "D5"], "q2": ["D7", "D9", "D6"], "q3": ["D6", "D4", "D8"], "q4": ["D2", "D1", "D3"]}

def score(run, k=3):
    rec, rr = 0, 0
    for q, docs in run.items():
        top = docs[:k]
        rec += len(gold[q] & set(top)) / len(gold[q])
        rr += next((1 / i for i, d in enumerate(top, 1) if d in gold[q]), 0)
    n = len(run)
    return rec / n, rr / n

for name, run in (("리랭커 전", before), ("리랭커 후", after)):
    r, m = score(run)
    print(f"{name}: Recall@3 {r:.3f} · MRR {m:.3f}")

# 출력
# 리랭커 전: Recall@3 0.625 · MRR 0.625
# 리랭커 후: Recall@3 1.000 · MRR 0.875
